use sa2_asset_tools::death_zones;
use sha2::{Digest, Sha256};

#[test]
#[ignore = "requires installed SA2_PC_EXE and SA2_DEATH_CONFIG generated by death_zone_reference.ps1"]
fn matches_sa_tools_across_all_death_zones() {
    let bytes = std::fs::read(std::env::var_os("SA2_PC_EXE").unwrap()).unwrap();
    let ini = std::fs::read_to_string(std::env::var_os("SA2_DEATH_CONFIG").unwrap()).unwrap();
    let tables = death_zones::read(&bytes, &ini).unwrap();
    assert_eq!(tables.len(), 50);
    assert_eq!(tables["City Escape Death Zones"].zones.len(), 3);
    let mut sorted = tables.values().collect::<Vec<_>>();
    sorted.sort_by_key(|t| t.rva);
    let mut hash = Sha256::new();
    for t in sorted {
        hash.update(t.rva.to_le_bytes());
        hash.update((t.zones.len() as u32).to_le_bytes());
        for z in &t.zones {
            hash.update(z.flags.to_le_bytes());
            hash.update(z.object_flags.to_le_bytes());
            for f in z.position {
                hash.update((if f == 0.0 { 0.0 } else { f }).to_le_bytes());
            }
            for a in z.angles {
                hash.update(a.to_le_bytes());
            }
            for f in z
                .scale
                .into_iter()
                .chain(z.bounds_center)
                .chain([z.bounds_radius])
            {
                hash.update((if f == 0.0 { 0.0 } else { f }).to_le_bytes());
            }
            hash.update((z.vertices.len() as u32).to_le_bytes());
            for v in z.vertices.iter().chain(&z.normals).flatten() {
                hash.update((if *v == 0.0 { 0.0 } else { *v }).to_le_bytes());
            }
            for w in z.material_words {
                hash.update(w.to_le_bytes());
            }
            hash.update(z.mesh_type.to_le_bytes());
            hash.update(z.mesh_material_index.to_le_bytes());
            hash.update((z.polygons.len() as u32).to_le_bytes());
            for p in &z.polygons {
                hash.update([u8::from(p.reversed)]);
                hash.update((p.indices.len() as u32).to_le_bytes());
                for i in &p.indices {
                    hash.update(i.to_le_bytes());
                }
            }
        }
    }
    assert_eq!(
        format!("{:x}", hash.finalize()),
        "909e148110784ed7f6e505331b7de62bba15033aa255032154bc5d1da6b0aa87"
    );
}

#[test]
fn rejects_an_unrecognized_executable() {
    assert!(death_zones::read(b"unsupported", "[zone]\ntype=deathzone\naddress=0").is_err());
}
